from solution import LRUCache
def test_a():
    c=LRUCache(2); c.put(1,1); c.put(2,2); assert c.get(1)==1
    c.put(3,3); assert c.get(2)==-1; c.put(4,4); assert c.get(1)==-1 and c.get(3)==3 and c.get(4)==4
def test_b():
    c=LRUCache(1); c.put(1,1); c.put(1,5); assert c.get(1)==5; c.put(2,2); assert c.get(1)==-1

from solution import parse_duration
import pytest
def test_a():
    assert parse_duration('1h30m15s')==5415 and parse_duration('45s')==45 and parse_duration('2h')==7200 and parse_duration('10m')==600
def test_b():
    for bad in ['', 'abc', '5x', '1h1h', 'h']:
        with pytest.raises(ValueError): parse_duration(bad)
